from pathlib import Path
import json,re
p=Path('outputs/Everyday Personal Dashboard.html');s=p.read_text()
wardrobe=json.loads(Path('work/updated-wardrobe.json').read_text())
def rep(a,b,label):
 global s
 if a not in s: raise SystemExit('missing anchor: '+label)
 s=s.replace(a,b,1)
# Replace embedded wardrobe with the newest workbook's 101 rows.
m=re.search(r'const seed=(.*?);\nconst navItems=',s,re.S)
if not m: raise SystemExit('embedded seed not found')
seed=json.loads(m.group(1));seed['wardrobe']=wardrobe
s=s[:m.start(1)]+json.dumps(seed,ensure_ascii=False,separators=(',',':'))+s[m.end(1):]
# Replace long flat navigation with five primary menus and three submenus.
start=s.index('const navItems=');end=s.index('\nconst initial=',start)
nav="""const navItems=[['home','⌂','Home'],['closet','◈','Closet'],['life','◇','Life'],['wellness','♥','Wellness'],['education','⌘','Study']];
const navGroups={closet:[['wardrobe','Wardrobe'],['outfits','Outfits'],['grooming','Grooming'],['care','Care']],life:[['events','Calendar'],['watchlist','Watchlist'],['reading','Reading'],['tasks','Tasks'],['journal','Journal']],wellness:[['nutrition','Food & nutrition'],['gym','Gym log'],['weight','Weight'],['cleaning','Cleaning rota']]};
const pageTitles={home:'Home',wardrobe:'Wardrobe',outfits:'Outfits',grooming:'Grooming',care:'Care',events:'Calendar',watchlist:'Watchlist',reading:'Reading',tasks:'Tasks',journal:'Journal',nutrition:'Food & nutrition',gym:'Gym log',weight:'Weight',cleaning:'Cleaning rota',education:'Study'};
function pageGroup(p){for(const [g,items] of Object.entries(navGroups))if(items.some(x=>x[0]===p))return g;return p;}"""
s=s[:start]+nav+s[end:]
# New defaults and migrate older browser data once, preserving user-added items and photos by exact item name.
a=s.index('const initial=');b=s.index('\nconst photoUrls=',a)
initial="""const initial={schemaVersion:2,wardrobe:seed.wardrobe.map((x,i)=>({...x,id:x.id||'w'+i,favorite:false})),outfits:[],grooming:seed.grooming.map((x,i)=>({...x,id:'g'+i})),events:[],watchlist:[],reading:[],tasks:[],gym:[],weight:[],nutrition:[],nutritionTargets:{calories:'',protein:''},cleaningWeek:'',cleaningChecks:{},careChecks:{},selectedOutfit:[],journal:[],pomodoro:{mode:'focus',remaining:1500,endsAt:0,sessions:0,running:false}};
let persisted={};try{persisted=JSON.parse(localStorage.getItem('everyday-personal-dashboard')||'{}')}catch{}
let state={...initial,...persisted};
if(persisted.schemaVersion!==2){const previous=persisted.wardrobe||[];state.wardrobe=initial.wardrobe.map(fresh=>{const old=previous.find(x=>x.Name===fresh.Name);return old?{...fresh,photoKey:old.photoKey,favorite:old.favorite||false,'Laundry Status':['Clean','Worn','In Wash','To Put Away'].includes(old['Laundry Status'])?old['Laundry Status']:'Clean'}:fresh}).concat(previous.filter(x=>x.id&&!/^w\\d+$/.test(x.id)&&!initial.wardrobe.some(n=>n.Name===x.Name)));state.schemaVersion=2;}"""
s=s[:a]+initial+s[b:]
# Additional page descriptions
rep("education:'Settle in, focus, and keep your studies moving.'};", "education:'Settle in, focus, and keep your studies moving.',nutrition:'Check campus menus and log what you eat.',cleaning:'A simple weekly reset for your room.'};", 'new descriptions')
# Replace page setter and renderer with grouped menus.
a=s.index('function setPage(p){');b=s.index('function countNote(',a)
render="""function setPage(p){page=p;searchTerm='';filter='All';render()}
function setNavGroup(group){if(group==='home'||group==='education'){setPage(group);return}if(pageGroup(page)===group)return;setPage(navGroups[group][0][0])}
function render(){const active=document.activeElement,keepSearch=active?.classList?.contains('search'),caret=keepSearch?active.selectionStart:null,placeholder=keepSearch?active.placeholder:'';document.getElementById('pagetitle').textContent=pageTitles[page]||'Home';document.getElementById('pagesub').textContent=descriptions[page]||'';let group=pageGroup(page);document.getElementById('nav').innerHTML=navItems.map(n=>`<button class=\\"${group===n[0]?'active':''}\\" onclick=\\"setNavGroup('${n[0]}')\\"><span class=\\"ico\\">${n[1]}</span>${n[2]}</button>`).join('');let sub=document.getElementById('subnav');sub.innerHTML=navGroups[group]?navGroups[group].map(n=>`<button class=\\"subnav-item ${page===n[0]?'active':''}\\" onclick=\\"setPage('${n[0]}')\\">${n[1]}</button>`).join(''):'';sub.hidden=!navGroups[group];let view=document.getElementById('view');view.innerHTML=({home:homeView,wardrobe:wardrobeView,outfits:outfitsView,journal:journalView,grooming:groomingView,care:careView,events:eventsView,watchlist:watchView,reading:readingView,tasks:tasksView,gym:gymView,weight:weightView,education:educationView,nutrition:nutritionView,cleaning:cleaningView}[page])();view.classList.toggle('edit-mode',editMode);let toggle=document.getElementById('editToggle');toggle.textContent=editMode?'✎ Edit mode: on':'✎ Edit mode: off';toggle.classList.toggle('active',editMode);if(keepSearch){const next=[...view.querySelectorAll('.search')].find(x=>x.placeholder===placeholder)||view.querySelector('.search');if(next){next.focus();if(caret!==null)next.setSelectionRange(caret,caret)}}if(page==='wardrobe'||page==='outfits')hydratePhotos();if(page==='education')updatePomodoroUI();}
"""
s=s[:a]+render+s[b:]
# The header groups are compact and the subnav adapts to tablet scrolling.
rep('<div id="view"></div>', '<nav id="subnav" class="subnav" aria-label="Section menu"></nav><div id="view"></div>', 'subnav element')
# Remove the single old location status and show storage as its own piece of wardrobe metadata.
rep(r"""<div class="garment-meta">${esc(x.Category)} · ${esc(x['Colour / Details'])}</div><div class="garment-actions"><select onchange="updateItem('wardrobe','${x.id}','Laundry Status',this.value)">${['Clean','Worn','In Wash','To Put Away'].map(st=>`<option ${x['Laundry Status']===st?'selected':''}>${st}</option>`).join('')}</select>""", r"""<div class="garment-meta">${esc(x.Category)} · ${esc(x['Colour / Details'])}</div><div class="garment-location"><span>Storage</span><b>${esc(x['Storage Location']||'Not specified')}</b><span class="pill">${esc(x['Wash Category']||'Wash group unset')}</span></div><div class="garment-actions"><select aria-label="Laundry status" onchange="updateItem('wardrobe','${x.id}','Laundry Status',this.value)">${['Clean','Worn','In Wash','To Put Away'].map(st=>`<option ${x['Laundry Status']===st?'selected':''}>${st}</option>`).join('')}</select>""", 'wardrobe details and status')
# New weekly room-cleaning rota and daily food log.
anchor='function eventsView(){'
features=r'''const roomCleaningItems=['Vacuum the floor','Wipe down surfaces','Clean the ice maker','Clean the water dispenser','Air-dust the room','Clean the sink'];
function weekStamp(){const d=new Date(),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.toISOString().slice(0,10)}
function ensureCleaningWeek(){const key=weekStamp();if(state.cleaningWeek!==key){state.cleaningWeek=key;state.cleaningChecks={};save()}}
function cleaningView(){ensureCleaningWeek();let done=roomCleaningItems.filter((_,i)=>state.cleaningChecks[i]).length;return `<div class=\\"wellness-hero\\"><div class=\\"eyebrow\\">ROOM RESET · WEEK OF ${fmtDate(state.cleaningWeek)}</div><h2>A fresh room, one small task at a time.</h2><p>Tick each job as you do it. This checklist resets automatically each Monday.</p><div class=\\"clean-progress\\"><i style=\\"width:${Math.round(100*done/roomCleaningItems.length)}%\\"></i></div><span class=\\"muted\\">${done} of ${roomCleaningItems.length} done this week</span></div><section class=\\"card cleaning-list\\">${roomCleaningItems.map((item,i)=>`<label class=\\"clean-task ${state.cleaningChecks[i]?'done':''}\\"><input type=\\"checkbox\\" ${state.cleaningChecks[i]?'checked':''} onchange=\\"state.cleaningChecks[${i}]=this.checked;save();render()\\"><span class=\\"clean-icon\\">${['⌁','✧','◈','◉','⟡','≈'][i]}</span><span>${item}</span><small>Weekly</small></label>`).join('')}</section>`}
function nutritionView(){let date=window.nutritionDate||new Date().toLocaleDateString('en-CA');let rows=state.nutrition.filter(x=>x.date===date).sort((a,b)=>(a.time||'').localeCompare(b.time||''));let calories=rows.reduce((n,x)=>n+(Number(x.calories)||0),0),protein=rows.reduce((n,x)=>n+(Number(x.protein)||0),0);let cgoal=Number(state.nutritionTargets.calories)||0,pgoal=Number(state.nutritionTargets.protein)||0;let pctC=cgoal?Math.min(100,Math.round(calories/cgoal*100)):0,pctP=pgoal?Math.min(100,Math.round(protein/pgoal*100)):0;let list=rows.map(x=>`<tr><td>${esc(x.time||'')}</td><td class=\\"rowname\\">${esc(x.name)}</td><td>${esc(x.meal||'')}</td><td>${Number(x.calories)||0} kcal</td><td>${Number(x.protein)||0} g</td><td><button class=\\"smallbtn edit-mode-only\\" onclick=\\"openForm('nutrition','${x.id}')\\">Edit</button><button class=\\"smallbtn\\" onclick=\\"removeItem('nutrition','${x.id}')\\">×</button></td></tr>`).join('');return `<section class=\\"nutrition-hero\\"><div><div class=\\"eyebrow\\">FUEL & FOOD</div><h2>Eat well, keep your day in view.</h2><p>Use the campus menu for ideas, then add calories and protein here when you eat.</p></div><a class=\\"btn primary\\" href=\\"https://netmenu.cbord.co.uk/NetNutrition/UniversityofReading\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Browse Reading menus ↗</a></section><div class=\\"nutrition-datebar\\"><label>Daily log date <input type=\\"date\\" class=\\"field\\" value=\\"${date}\\" onchange=\\"window.nutritionDate=this.value;render()\\"></label><button class=\\"btn primary\\" onclick=\\"openForm('nutrition')\\">＋ Log food</button></div><div class=\\"grid stats nutrition-stats\\">${countNote('Calories',calories.toLocaleString()+' kcal',cgoal?`${pctC}% of your personal target`:'set an optional target below')}${countNote('Protein',protein+' g',pgoal?`${pctP}% of your personal target`:'set an optional target below')}</div><div class=\\"nutrition-bars\\"><div><span>Calories ${cgoal?`· target ${cgoal}`:''}</span><div class=\\"clean-progress\\"><i style=\\"width:${pctC}%\\"></i></div></div><div><span>Protein ${pgoal?`· target ${pgoal} g`:''}</span><div class=\\"clean-progress protein-progress\\"><i style=\\"width:${pctP}%\\"></i></div></div></div><section class=\\"card nutrition-log\\"><div class=\\"cardhead\\"><h2>Food log · ${fmtDate(date)}</h2><button class=\\"smallbtn\\" onclick=\\"toggleTargets()\\">Daily targets</button></div><div id=\\"targetEditor\\" ${window.showNutritionTargets?'':'hidden'} class=\\"target-editor\\"><label>Calories target <input class=\\"field\\" type=\\"number\\" min=\\"0\\" value=\\"${cgoal||''}\\" onchange=\\"state.nutritionTargets.calories=this.value;save();render()\\"></label><label>Protein target (g) <input class=\\"field\\" type=\\"number\\" min=\\"0\\" value=\\"${pgoal||''}\\" onchange=\\"state.nutritionTargets.protein=this.value;save();render()\\"></label></div>${table(['Time','Food / drink','Meal','Calories','Protein',''],list)}</section><p class=\\"muted\\" style=\\"font-size:11px\\">Targets are optional personal settings, not dietary recommendations. Nutrition values can vary by serving size; use the menu or product label when available.</p>`}
function toggleTargets(){window.showNutritionTargets=!window.showNutritionTargets;render()}
'''
rep(anchor,features+anchor,'nutrition and cleaning views')
# Daily nutrition form fields and add/update records.
rep("const configs={wardrobe:", "const configs={nutrition:{title:'Log food or drink',fields:[['date','Date','date','required'],['time','Time','time'],['name','Food / drink','text','required'],['meal','Meal','select','',['Breakfast','Lunch','Dinner','Snack','Drink']],['calories','Calories (kcal)','number'],['protein','Protein (g)','number']]},wardrobe:", 'nutrition form config')
# New meal defaults to selected day; date field for other forms remains unchanged.
rep("function openForm(type,id=''){let c=configs[type];if(!c)return;let item=id?state[type].find(x=>x.id===id):null;let values={};", "function openForm(type,id=''){let c=configs[type];if(!c)return;let item=id?state[type].find(x=>x.id===id):null;let values={};if(type==='nutrition'&&!item)values.date=window.nutritionDate||new Date().toLocaleDateString('en-CA');", 'nutrition form date')
# Add numerical field normalization for nutrition, and retain addition/edit functionality.
rep("for(const k of ['episode','season','current','total','load','value'])", "for(const k of ['episode','season','current','total','load','value','calories','protein'])", 'nutrition number parse')
# Header group CSS / tablet adjustments
rep('</style>',r'''/* Compact tablet navigation and wellness sections */
.subnav{display:flex;gap:8px;align-items:center;overflow-x:auto;scrollbar-width:none;padding:2px 0 13px;margin:-10px 0 11px}.subnav::-webkit-scrollbar{display:none}.subnav-item{flex:0 0 auto;border:1px solid #2a3d52;background:#0d1726;color:#a4bad0;border-radius:99px;padding:8px 14px;font-size:12px;white-space:nowrap}.subnav-item:hover,.subnav-item.active{background:#12333a;border-color:#53d9c8;color:#8bf4df;box-shadow:0 0 15px #46ddce18}.subnav[hidden]{display:none}.garment-location{display:flex;align-items:center;gap:7px;color:#92a5ba;font-size:10px;margin:8px 0;flex-wrap:wrap}.garment-location b{color:#d4e6f7;font-size:11px}.wellness-hero,.nutrition-hero{border:1px solid #314860;border-radius:19px;background:radial-gradient(circle at 88% 20%,#193944 0,transparent 33%),linear-gradient(115deg,#101c2c,#17162b);padding:23px;margin-bottom:15px}.wellness-hero h2,.nutrition-hero h2{margin:5px 0;font-size:23px;letter-spacing:-.035em}.wellness-hero p,.nutrition-hero p{margin:0 0 13px;color:#9bb0c4;font-size:13px}.clean-progress{height:8px;background:#26364a;border-radius:99px;overflow:hidden;margin:12px 0 8px}.clean-progress i{height:100%;display:block;border-radius:99px;background:linear-gradient(90deg,#34c8be,#8579ff);transition:width .3s ease}.cleaning-list{padding:5px 18px}.clean-task{display:flex;align-items:center;gap:13px;padding:15px 4px;border-bottom:1px solid #27374b;color:#deebf7;cursor:pointer}.clean-task:last-child{border:0}.clean-task input{width:19px;height:19px;accent-color:#62e8d5}.clean-task.done span:not(.clean-icon){text-decoration:line-through;color:#72869b}.clean-icon{color:#77e9d5;font-size:17px;width:22px;text-align:center}.clean-task small{margin-left:auto;color:#7990a6}.nutrition-hero{display:flex;justify-content:space-between;align-items:center;gap:14px}.nutrition-hero .btn{white-space:nowrap;text-decoration:none}.nutrition-datebar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:14px 0}.nutrition-datebar label,.target-editor label{display:flex;align-items:center;gap:9px;color:#9cb0c4;font-size:12px}.nutrition-stats{grid-template-columns:repeat(2,1fr);margin:8px 0 12px}.nutrition-bars{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:16px;color:#a1b4c7;font-size:11px}.protein-progress i{background:linear-gradient(90deg,#a57aff,#e078bb)}.target-editor{display:flex;gap:12px;flex-wrap:wrap;padding:11px 0 15px}.target-editor[hidden]{display:none}.target-editor input{width:120px}.nav button{min-height:42px}.main{max-width:1280px}
@media(max-width:900px){.subnav{margin:0 0 9px;padding:3px 0 12px}.nutrition-hero{align-items:flex-start;flex-direction:column}.wellness-hero,.nutrition-hero{padding:19px}.nutrition-datebar{align-items:flex-start;flex-direction:column}.education-grid{grid-template-columns:1fr}}
@media(max-width:620px){.subnav-item{padding:8px 12px}.nutrition-bars{grid-template-columns:1fr}.nutrition-datebar label{width:100%;justify-content:space-between}.nutrition-datebar input{flex:1}.garment-location{font-size:9px}.cleaning-list{padding:5px 12px}.clean-task{gap:9px}.top{gap:10px}.title{font-size:25px}}
</style>''','tablet and nutrition style')
p.write_text(s)
print('dashboard patch size',p.stat().st_size)
